			/*
			 * 그리드에서 row-check 이벤트 발생 시 호출.
			 * Grid의 RowCheckbox가 체크 되었을 때 발생하는 이벤트. (columnType=checkbox)
			 */
			function onGrdListRowCheck(e){
			    var grdList = e.control;
			    var vnRowIdx = e.rowIndex;    
			    
			    var vaHdrCellIdxs = grdList.header.getCellIndices();
			    var vaHdrCell = grdList.getColumnLayout().header;
			    
			    if(vaHdrCellIdxs.length < 1) return false;
			    
			    vaHdrCellIdxs.forEach(function(cellIdx){
			        var vbHdrVisble = vaHdrCell[cellIdx].visible;
			        
			        // 숨김 컬럼일경우 예외처리
			        if(!vbHdrVisble) return false;
			        
			        var vsColNm = grdList.detail.getColumn(cellIdx).columnName;
			        
			        // 사용자명, ID 컬럼 예외처리
			        if(vsColNm == "AUTHRT_ID" || vsColNm == "AUTHRT_ID2" || vsColNm == "AUTHRT_NM") return false;   
			        
			        grdList.setCellValue(vnRowIdx, cellIdx, "Y");
			    });
			      
			}

			/*
			 * 그리드에서 row-uncheck 이벤트 발생 시 호출.
			 * Grid의 RowCheckbox가 체크 해제되었을 때 발생하는 이벤트. (columnType=checkbox)
			 */
			function onGrdListRowUncheck(e){
			    var grdList = e.control;
			    var vnRowIdx = e.rowIndex;    
			    
			    var vaHdrCellIdxs = grdList.header.getCellIndices();
			    var vaHdrCell = grdList.getColumnLayout().header;
			    
			    if(vaHdrCellIdxs.length < 1) return false;
			    
			    vaHdrCellIdxs.forEach(function(cellIdx){
			        var vbHdrVisble = vaHdrCell[cellIdx].visible;
			        
			        // 숨김 컬럼일경우 예외처리
			        if(!vbHdrVisble) return false;
			        
			        var vsColNm = grdList.detail.getColumn(cellIdx).columnName;
			        
			        // 사용자명, ID 컬럼 예외처리
			        if(vsColNm == "AUTHRT_ID" || vsColNm == "AUTHRT_ID2" || vsColNm == "AUTHRT_NM") return false;   
			        
			        grdList.setCellValue(vnRowIdx, cellIdx, "N");
			    });
			}

